'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=n=>'$'+Math.round(n).toLocaleString('en-US'),million=n=>'$'+(n/1e6).toFixed(2)+'M',pct=n=>(n*100).toFixed(1)+'%';
const sections=[['billing','▤','Billing & Collection'],['revenue','↗','Revenue & Changes'],['profit','◫','Leasing Profitability Analysis'],['contracts','▥','Contracts & Change Events'],['scope','◎','AI Capabilities']];
const seed=[['Global Telecom Operator','Telecom','United States',2080000,2000000,.12,.30,36000,51360],['Retail Technology Group','Retail Technology','Germany',1500000,2400000,.14,.22,15000,30000],['Healthcare Equipment Leasing','Healthcare Equipment','Singapore',1160000,1900000,.18,.33,5800,11600],['North America Data Center Operator','Data Centers','United States',1830000,1200000,.22,.35,-9150,-9150],['Cloud Infrastructure Provider','Cloud Services','Germany',1330000,800000,.24,.38,-6650,-6650]];
const extraNames=['European Network Operator','Asia Pacific Retail Equipment Group','North America Healthcare Services','Asia Data Center Operator','Global Cloud Infrastructure Provider','Regional Telecom Customer','European Retail Technology'];
const accounts=Array.from({length:12},(_,i)=>{const s=seed[i%5],factor=i<5?1:.35+(i%4)*.12,rev=Math.round(s[3]*factor),ar=Math.round(s[4]*factor);return {id:i,code:'ACC-'+String(i+1).padStart(4,'0'),name:i<5?s[0]:extraNames[i-5],kind:i%5,industry:s[1],country:s[2],revenue:rev,ar,hwMargin:s[5],serviceMargin:s[6],hwIncrease:Math.round(s[7]*factor),serviceIncrease:Math.round(s[8]*factor),renewal:i%5===0?5200000*factor:rev*2.2,approvedChange:i%5<2?-Math.round(rev*(i%5===0?180000/2080000:.06)):0,owner:['Finance BP · Alex','AR Owner · Jamie','Account Owner · Sam'][i%3]}});
const STORAGE='nexbill-ai-support-loop-v1';let store={accounts:{}};try{const parsed=JSON.parse(localStorage.getItem(STORAGE)||'null');if(parsed&&typeof parsed.accounts==='object'&&parsed.accounts)store=parsed}catch{}
const ui={account:0,open:true,aiTab:'monitor',evidence:'external',billingStatus:'all',profitDimension:'tranche',profitScope:'current',profitSlice:null,reportTab:'forecast',watch:false,watchFilter:'all',search:'',repricing:0,servicePackage:0};
const edits=Object.create(null);
function state(id=ui.account){return store.accounts[id]||{step:0,feedback:{},decisions:[],updates:[],paused:false}}
function c(){return accounts[ui.account]}
function activeDecision(id=ui.account){return state(id).decisions.at(-1)||null}
function saveState(id,next,message){const proposed={...store,accounts:{...store.accounts,[id]:next}};try{localStorage.setItem(STORAGE,JSON.stringify(proposed))}catch{toast('The browser could not save the record, No changes were saved. Retain your input and try again. ');return false}store=proposed;if(message)toast(message);return true}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function dialog(title,html){$('#dialog-content').innerHTML=`<h2>${esc(title)}</h2>${html}`;$('#detail-dialog').showModal()}
function page(){const p=location.hash.slice(1);return sections.some(s=>s[0]===p)?p:'billing'}
function dataDate(id=ui.account){return ['2026-09-29','2026-09-30','2026-10-02','2026-10-07','2026-10-09'][state(id).step]||'2026-09-29'}
function metrics(a){const step=state(a.id).step,hwRev=Math.round(a.revenue*.7),svRev=a.revenue-hwRev,hwCost=Math.round(hwRev*(1-a.hwMargin)),svCost=Math.round(svRev*(1-a.serviceMargin))+(step>=4?Math.round(a.revenue*.03):0),cost=hwCost+svCost,priorCost=hwCost-a.hwIncrease+(Math.round(svRev*(1-a.serviceMargin))-a.serviceIncrease);return {revenue:a.revenue,hwRev,svRev,hwCost,svCost,cost,gp:a.revenue-cost,margin:(a.revenue-cost)/a.revenue,priorCost,priorGP:a.revenue-priorCost,priorMargin:(a.revenue-priorCost)/a.revenue,hwIncrease:a.hwIncrease,svIncrease:a.serviceIncrease+(step>=4?Math.round(a.revenue*.03):0)}}
function invoices(a){const specs=[[.6,.2,'2026-10-15','2026-09-01'],[.35,0,'2026-09-20','2026-08-20'],[.25,0,'2026-10-30','2026-09-20'],[.3,.3,'2026-09-01','2026-08-01']];return specs.map((s,i)=>{const amount=Math.round(a.ar*s[0]),paid=Math.round(a.ar*s[1])+(i===1&&state(a.id).step>=3?Math.round(a.ar*.2):0),open=amount-paid,overdue=open>0&&s[2]<dataDate(a.id);return {id:'960'+String(a.id+1).padStart(3,'0')+String(i+1).padStart(3,'0'),issued:s[3],due:s[2],amount,paid,open,status:!open?'Paid':overdue?'Overdue':paid?'Partially Paid':'Awaiting Payment',tranche:'TR-'+String(a.id+1).padStart(3,'0')+'-'+(i%3+1)}})}
function arMetrics(a){const inv=invoices(a);return {open:inv.reduce((n,x)=>n+x.open,0),overdue:inv.filter(x=>x.status==='Overdue').reduce((n,x)=>n+x.open,0),paid:inv.reduce((n,x)=>n+x.paid,0)}}
function forecast(a){return {standard:a.revenue*3,change:a.approvedChange,baseline:a.revenue*3+a.approvedChange,pending:-Math.round(a.revenue*.14423)}}
function sourceEvents(a){let events;if(a.kind<3)events=[{id:'E1',date:'2026-09-29',title:a.kind===0?'Workforce and operating footprint reduction announced':a.kind===1?'Store and operating cost reduction program':'Equipment investment approvals take longer',source:'Customer announcement (Simulation)',body:'An operating adjustment program was announced, Future usage and procurement budgets may be affected; This does not mean that Nexbill contracts have changed. ',type:'business',adverse:true,verified:true,association:true},{id:'E2',date:'2026-09-24',title:'Credit outlook revised to negative',source:'Credit monitoring summary (Simulation)',body:'A signal of future funding and liquidity pressure, Validate against aging and payment records; This does not establish a default. ',type:'credit',adverse:true,verified:true,association:true},{id:'E3',date:'2026-09-18',title:'Industry capital investment slows',source:'Industry investment briefing (Simulation)',body:'New industry projects face delays, Customer expansion and renewal budgets may be affected, Industry context is not a confirmed contract reduction. ',type:'business',adverse:true,verified:true,association:true}];else events=[{id:'E1',date:'2026-09-29',title:'New facilities and expansion announced',source:'Customer business announcement (Simulation)',body:'Expansion plans align with historical usage growth, Confirm budget and procurement timing early, Do not recognize this as revenue. ',type:'business',adverse:false,verified:true,association:true},{id:'E2',date:'2026-09-24',title:'Financing plans remain stable',source:'Customer financial disclosure summary (Simulation)',body:'Current disclosures show no new credit deterioration; Continue reviewing subsequent disclosures and payment records. ',type:'credit',adverse:false,verified:true,association:true},{id:'E3',date:'2026-09-18',title:'Industry demand continues to grow',source:'Industry demand briefing (Simulation)',body:'Demand growth supports an expansion discussion, However, procurement, contracting and revenue recognition occur at different times. ',type:'business',adverse:false,verified:true,association:true}];events.push({id:'E4',date:'2026-09-29',title:'Restructuring rumor concerns a similarly named company',source:'Unverified media lead (Simulation)',body:'The entity name is similar, but the legal entity has not been matched, and no original disclosure is available. This lead is excluded from financial scenarios. ',type:'business',adverse:true,verified:false,association:false});if(state(a.id).step>=1)events.unshift({id:'E5',date:'2026-09-30',title:'New credit downgrade disclosed',source:'Credit update notification (Simulation)',body:'The disclosure increases payment uncertainty, Review whether the recorded customer decision remains appropriate. ',type:'credit',adverse:true,verified:true,association:true});if(state(a.id).step>=2)events.unshift({id:'E6',date:'2026-10-02',title:a.kind<3?'Company clarifies the impact of industry investment changes':'Company clarifies expansion scope',source:'Supplementary company disclosure (Simulation)',body:a.kind<3?'The clarification confirms that, industry delays do not affect current core facility projects; Original E3 no longer supports this customer’s downside scenario. Credit signals still require separate review. ':'The clarification narrows demand growth to specific facilities, E3 ’s broad growth assumption no longer applies. Validate each new opportunity separately. ',type:'business',adverse:false,verified:true,association:true});return events.map(e=>{const f=state(a.id).feedback[e.id];return {...e,excluded:f==='exclude',association:f==='link'?true:e.association,superseded:e.id==='E3'&&state(a.id).step>=2&&state(a.id).feedback.E6!=='exclude'}})}
function acceptedSignals(a){return sourceEvents(a).filter(e=>e.adverse&&e.verified&&e.association&&!e.excluded&&!e.superseded)}
function outlook(a){const n=acceptedSignals(a).length,f=forecast(a),low=n?Math.min(.16,.02+n*.02):0,high=n?Math.min(.2,.03+n*.03):0;return {n,low,high,lower:f.baseline*(1-high),upper:f.baseline*(1-low),exposureLow:f.baseline*low,exposureHigh:f.baseline*high,baseline:f.baseline}}
function recommendation(a){const o=outlook(a);return o.n>=2?'Maintain pricing, prepare a retention option, and intensify collection follow-up':o.n===1?'Maintain the current approach, Verify credit changes before adjusting terms':a.kind>2?'Validate expansion budget and timing, Prepare a scoped service proposal':'Maintain the current approach, Continue reviewing revenue and collection'}
const ruleNames={credit:'New credit downgrade or outlook deterioration',business:'Material operating or investment plan change',ar:'Increase in overdue receivables',margin:'Further decline in gross margin',review:'Scheduled review date reached'};
function pendingReviews(id=ui.account){const s=state(id),d=activeDecision(id);if(!d)return [];const updates=s.updates.filter(u=>u.step>d.baselineStep&&u.triggered.length);if(dataDate(id)>=d.nextReview&&!s.paused)updates.push({step:s.step,title:'The account review date has been reached',triggered:['review']});return updates}
function accountOptions(){const q=ui.search.toLowerCase();return accounts.filter(a=>(a.name+' '+a.code+' '+a.industry).toLowerCase().includes(q))}
function accountContext(){const a=c(),m=metrics(a),ar=arMetrics(a);return `<section class="account-context"><div class="context-controls"><input id="account-search" aria-label="Search Accounts" value="${esc(ui.search)}" placeholder="Search name / Account ID"><select id="account-select" aria-label="Select Account">${accountOptions().map(x=>`<option value="${x.id}" ${x.id===ui.account?'selected':''}>${esc(x.name)} · ${x.code}</option>`).join('')||'<option value="" disabled>No matching accounts</option>'}</select></div><div class="context-top"><div><div class="account-name">${esc(a.name)}</div><div class="context-meta">${a.code} · ${a.industry} · ${a.country} · ${a.owner}</div></div><span class="status">Nexbill Business Records</span></div><div class="context-stats"><span>Recognized Revenue This Month<b>${million(m.revenue)}</b></span><span>Current Open AR<b>${million(ar.open)}</b></span><span>Current Gross Margin<b>${pct(m.margin)}</b></span></div></section>`}
function pageIntro(title,sub,exportable=false){return `<div class="page-intro"><div><div class="section-label">NEXBILL / FINANCE & ACCOUNTING</div><h1>${title}</h1><p>${sub}</p></div>${exportable?'<button data-command="export">↓ Export Current Report</button>':''}</div>`}
function billingPage(){const a=c(),rows=invoices(a).filter(x=>ui.billingStatus==='all'||x.status===ui.billingStatus);return pageIntro('Billing & Collection','Invoice Payment Status Tracking · Review invoices, payments and outstanding balances in the business workspace. ',true)+accountContext()+`<div class="connected-hint"><i></i> The right-side AI Copilot follows the selected account, Combining history, recent business records and external signals. </div><section class="native-section"><div class="native-section-head"><h2>Customer Invoices & Payment Status</h2><small>Snapshot Date: ${dataDate()}</small></div><div class="toolbar"><label>Payment Status<select id="invoice-status"><option value="all">All Statuses</option>${['Awaiting Payment','Partially Paid','Overdue','Paid'].map(s=>`<option ${ui.billingStatus===s?'selected':''}>${s}</option>`).join('')}</select></label><span class="muted" style="font-size:10px">External Customer AR · USD</span></div><div class="table-scroll"><table><thead><tr><th>Invoice / Tranche</th><th>Due Date</th><th>Invoice Amount</th><th>Payments Received</th><th>Open Amount</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="table-link" data-invoice="${x.id}">${x.id}</button><small>${x.tranche}</small></td><td>${x.due}</td><td>${usd(x.amount)}</td><td>${usd(x.paid)}</td><td>${usd(x.open)}</td><td><span class="status ${x.status==='Overdue'?'red':x.status==='Paid'?'green':''}">${x.status}</span></td></tr>`).join('')||'<tr><td colspan="6" class="zero-state">No invoices match the current filter</td></tr>'}</tbody></table></div><div class="native-footnote">${rows.length}  records · Invoices and payments are illustrative snapshots; Invoice amounts are not recognized revenue. </div></section><div class="native-note"><b>Business execution remains in Nexbill</b><br>Invoice, collection and accounting follow established workflows. Copilot explains the implications, supports decisions and retains review context. </div>`}
function revenuePage(){const a=c(),f=forecast(a);return pageIntro('Revenue & Changes','Separate standard transactions and Change Events change events, to establish a traceable revenue baseline. ',ui.reportTab!=='pn')+accountContext()+`<section class="native-section"><div class="plain-tabs"><button data-report-tab="forecast" class="${ui.reportTab==='forecast'?'active':''}">Revenue Forecast</button><button data-report-tab="pn" class="${ui.reportTab==='pn'?'active':''}">PN report</button></div>${ui.reportTab==='pn'?`<div class="inset"><h2>PN report · Report Definition Pending</h2><p class="compact-note">The requested base report entry is retained. Available requirements cover customers, Contracts, Tranche, billing and revenue dimensions; PN report requires the report owner to confirm its definition and fields, It is not assumed to mean P&L. </p><button class="secondary" data-report-tab="forecast">View Revenue Baseline →</button></div>`:`<div class="revenue-equation"><div>Q4 Standard Transactions<b>${million(f.standard)}</b></div><span>＋</span><div>Confirmed Change Events<b>${f.change<0?'−':''}${million(Math.abs(f.change))}</b></div><span>＝</span><div>Current Revenue Forecast<b>${million(f.baseline)}</b></div></div><div class="table-scroll"><table><thead><tr><th>Revenue Component</th><th>10  Month</th><th>11  Month</th><th>12  Month</th><th>Recognition Basis</th></tr></thead><tbody><tr><td>Standard Transactions</td><td>${usd(a.revenue)}</td><td>${usd(a.revenue)}</td><td>${usd(a.revenue)}</td><td>Signed Contracts / Payment Schedule</td></tr><tr><td>Confirmed Change Events</td>${[1,2,3].map(()=>`<td>${usd(f.change/3)}</td>`).join('')}<td>Confirmed Change Records</td></tr><tr><td><b>Current Forecast</b></td>${[1,2,3].map(()=>`<td><b>${usd(f.baseline/3)}</b></td>`).join('')}<td>Excludes external-signal scenarios</td></tr></tbody></table></div><div class="native-footnote">Pending Changes ${usd(f.pending)} Excluded from baseline. External signals support scenario review only, They are not confirmed contract changes. </div>`}</section><div class="native-note"><b>Base reports explain“the recorded facts”</b><br>AI then adds external operating and credit signals, to explain potential pressure on future revenue, and identify assumptions requiring validation. </div>`}
function allocate(value,share,index){return index===2?value-Math.round(value*.5)-Math.round(value*.3):Math.round(value*share)}
function trancheRows(){const pool=ui.profitScope==='all'?accounts:[c()];return pool.flatMap(a=>{const m=metrics(a);return [.5,.3,.2].map((share,i)=>({account:a.id,name:a.name,country:i===1?(a.country==='United States'?'Germany':'United States'):a.country,tranche:'TR-'+String(a.id+1).padStart(3,'0')+'-'+(i+1),hwRev:allocate(m.hwRev,share,i),svRev:allocate(m.svRev,share,i),hwCost:allocate(m.hwCost,share,i),svCost:allocate(m.svCost,share,i),priorCost:allocate(m.priorCost,share,i)}))})}
function profitRows(){const map=new Map();for(const row of trancheRows()){const key=ui.profitDimension==='country'?row.country:ui.profitDimension==='customer'?row.name:row.tranche;if(!map.has(key))map.set(key,{key,account:row.account,hwRev:0,svRev:0,hwCost:0,svCost:0,priorCost:0,count:0});const g=map.get(key);for(const f of ['hwRev','svRev','hwCost','svCost','priorCost'])g[f]+=row[f];g.count++}return [...map.values()].map(r=>({...r,revenue:r.hwRev+r.svRev,gp:r.hwRev+r.svRev-r.hwCost-r.svCost,margin:(r.hwRev+r.svRev-r.hwCost-r.svCost)/(r.hwRev+r.svRev)}))}
function profitabilityPage(){const rows=profitRows(),rev=rows.reduce((s,r)=>s+r.revenue,0),gp=rows.reduce((s,r)=>s+r.gp,0);return pageIntro('Leasing Profitability Analysis','By Customer, Country, Tranche understand leasing performance, Separate hardware and service contributions. ',true)+accountContext()+`<section class="native-section"><div class="native-section-head"><h2>Customer / Country / Tranche Revenue & Cost Table</h2><small>Illustrative Monthly Basis · USD</small></div><div class="toolbar"><label>Scope<select id="profit-scope"><option value="current" ${ui.profitScope==='current'?'selected':''}>Current Account</option><option value="all" ${ui.profitScope==='all'?'selected':''}>All 12  accounts</option></select></label><label>Analysis Dimension<select id="profit-dimension">${[['tranche','Tranche'],['customer','Customer'],['country','Country']].map(([v,t])=>`<option value="${v}" ${ui.profitDimension===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="summary-strip"><div>Revenue in Selected Scope<strong>${million(rev)}</strong></div><div>Gross Profit<strong>${million(gp)}</strong></div><div>Gross Margin<strong>${pct(gp/rev)}</strong></div></div><div class="table-scroll"><table><thead><tr><th>${{tranche:'Tranche',customer:'Customer',country:'Country'}[ui.profitDimension]}</th><th>Hardware Revenue / Cost</th><th>Service Revenue / Cost</th><th>Gross Margin</th><th>AI Assistance</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.key)}<small>${r.count}  items Tranche</small></td><td>${usd(r.hwRev)}<small>Cost ${usd(r.hwCost)}</small></td><td>${usd(r.svRev)}<small>Cost ${usd(r.svCost)}</small></td><td>${pct(r.margin)}</td><td><button class="explain-cell" data-explain-profit="${i}">✦ Explain Variance</button></td></tr>`).join('')}</tbody></table></div><div class="native-footnote">Hardware and services are allocated separately; Cost allocations are illustrative assumptions. AI The explanation uses the same scope as the table, Avoid mixing financial dimensions. </div></section>`}
function contractsBase(){const a=c(),f=forecast(a);return pageIntro('Contracts & Change Events','Review changes and processing status, AI does not convert external signals into contract changes. ')+accountContext()+`<section class="native-section"><div class="native-section-head"><h2>Subscription Lifecycle Records</h2><small>${a.code}</small></div><div class="table-scroll" style="margin-top:18px"><table><thead><tr><th>Event / Request ID</th><th>Status</th><th>Effective Date</th><th>Revenue Impact</th><th>Details</th></tr></thead><tbody><tr><td>Standard Subscription Transaction<small>SUB-${a.code}</small></td><td><span class="status green">Active</span></td><td>2026-07-01</td><td>${million(f.standard)} / Q4</td><td>Payment schedule generated</td></tr><tr><td>Confirmed Contract Change<small>CE-${a.code}-01</small></td><td><span class="status green">Confirmed</span></td><td>2026-10-01</td><td>${usd(f.change)} / Q4</td><td>Included in revenue baseline</td></tr><tr><td>Flex down Request<small>CE-${a.code}-02</small></td><td><span class="status amber">Awaiting Approval</span></td><td>To Be Confirmed</td><td>${usd(f.pending)} / Scenario</td><td>Excluded from revenue baseline</td></tr></tbody></table></div><div class="native-footnote">Workflow based on KUT  of  Change Event Report and subscription change processes. All records are illustrative. </div></section><div class="native-note">AI supports assessment of financial implications. Actual contract changes, approvals and posting remain in Nexbill business workflows. </div>`}
function scopePage(){return pageIntro('AI Capabilities & Responsibilities','Business signal monitoring and profitability interpretation are priorities; Base reports supply facts, Repricing supports recommendations. ')+`<section class="native-section inset"><div class="capacity-head">Start with business facts, form a financial interpretation, then review the decision</div><div class="capability-list">${[['01','PN report','Details','Retain the report entry, organize business facts. The report owner confirms definitions and fields. '],['02','Revenue Forecast','Details + AI Interpretation','Standard transactions and Change Events form separate baseline components; AI uses new operating signals to assess pressure scenarios. '],['03','Business Signal Monitoring','AI Priority','Verify entity and source, Identify credit, operating, and industry changes; Link account exposure and existing decisions, Prompt a review when assumptions change. '],['04','Billing / Receivables','Details + AI Interpretation','Show current billing and payment status; Connect aging changes with external pressure, Arrange early follow-up. '],['05','Leasing Profitability','AI Priority','By Customer, Country, Tranche Identify margin changes, Separate hardware and services, Explain cost and contract drivers. '],['06','Repricing','Supporting Recommendation','Consider gross margin, service scope and account risk, Compare pricing and contract terms; Contracts are not changed automatically. ']].map(([n,title,type,desc])=>`<div class="capability-row"><span class="num">${n}</span><div><b>${title}</b><br><span class="status ${type==='AI Priority'?'purple':''}">${type}</span></div><p>${desc}</p></div>`).join('')}</div></section><section class="native-section inset"><h2>Reviewing the decision</h2><p class="compact-note">Historical and latest data + External signals → Account impact assessment → Finance decision → Save account context → Monitor new changes → Review the prior decision. </p><p class="compact-note">In this prototype“saving context”retains account decisions, evidence and review conditions, for later reference; It does not train a model or connect to production. Simulation updates are loaded by clicking, No background data collection is running. </p><button class="secondary" data-command="sources">View Design References</button></section>`}
function hostRender(){const p=page();$('#page-name').textContent=sections.find(s=>s[0]===p)[2];$('#host-nav').innerHTML=sections.map(([id,icon,name])=>`<a href="#${id}" class="${p===id?'active':''}" ${p===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}</a>`).join('');$('#business-main').innerHTML=({billing:billingPage,revenue:revenuePage,profit:profitabilityPage,contracts:contractsPage,scope:scopePage})[p]()+`<div class="host-caption">Nexbill Business Workspace Mockup · Illustrative snapshots · AI No transactions executed</div>`;document.body.classList.toggle('ai-closed',!ui.open);$('#review-count').textContent=accounts.filter(a=>pendingReviews(a.id).length).length}
function assistantRender(){const a=c();$('#assistant').innerHTML=`<div class="assistant-head"><div class="assistant-heading"><h2><span class="ai-symbol">✦</span>Finance Copilot</h2><button class="icon-button" data-command="close-ai" aria-label="Collapse AI Copilot">×</button></div><p class="assistant-subtitle">Nexbill embedded AI support · History × New Data × External Signals</p><div class="assistant-context"><strong title="${esc(a.name)}">${ui.profitSlice&&ui.aiTab==='profit'?esc(ui.profitSlice.key):esc(a.name)}</strong><span>${ui.profitSlice&&ui.aiTab==='profit'?'Profitability Scope':a.code}</span></div></div><div class="ai-tabs" role="tablist" aria-label="Copilot Functions">${[['monitor','Account Monitoring'],['profit','Profitability Insights'],['decision','Watch & Review']].map(([v,t])=>`<button role="tab" aria-selected="${ui.aiTab===v&&!ui.watch}" data-ai-tab="${v}" class="${ui.aiTab===v&&!ui.watch?'active':''}">${t}</button>`).join('')}</div><div class="assistant-body">${ui.watch?watchPanel():ui.aiTab==='monitor'?monitorPanel():ui.aiTab==='profit'?profitPanel():decisionPanel()}</div><div class="assistant-foot">Illustrative signals and data · New events appear when simulation updates are loaded · No transactions executed</div>`}
function render(){hostRender();assistantRender()}
function evidencePanel(){const a=c(),m=metrics(a),ar=arMetrics(a),f=forecast(a);if(ui.evidence==='history')return `<div class="evidence-item"><div class="evidence-top"><button class="evidence-title" data-evidence="H1">Six-month revenue is near current levels</button><span class="evidence-ref">H1</span></div><div class="evidence-meta">Historical Recognized Revenue · Revenue reporting (Simulation)</div><div class="mini-history" role="img" aria-label="Illustrative Six-Month Revenue Trend">${[.96,.98,.97,.99,.998,1].map((v,i)=>`<div style="height:${v*46}px"><span>${i+4}  Month</span></div>`).join('')}</div><div class="mini-history-label">Historical Monthly Average ${million(a.revenue*.983)} · Latest Month ${million(a.revenue)}</div></div><div class="evidence-item"><div class="evidence-top"><button class="evidence-title" data-evidence="H2">Historical Gross Margin ${pct(m.priorMargin)} → Current ${pct(m.margin)}</button><span class="evidence-ref">H2</span></div><div class="evidence-meta">Consistent Scope Comparison · Hardware / Service Cost (Simulation)</div></div>`;if(ui.evidence==='latest')return `<div class="evidence-item"><div class="evidence-top"><button class="evidence-title" data-evidence="N1">Open AR ${million(ar.open)}, of which overdue ${million(ar.overdue)}</button><span class="evidence-ref">N1</span></div><p class="evidence-body">From the current payment snapshot ${dataDate()}, Check payment status in the invoice records. </p></div><div class="evidence-item"><div class="evidence-top"><button class="evidence-title" data-evidence="N2">Revenue Baseline: Standard Transactions + Confirmed Changes</button><span class="evidence-ref">N2</span></div><p class="evidence-body">Q4 ${million(f.standard)} + ${usd(f.change)} = ${million(f.baseline)}; Pending changes are excluded from the baseline. </p></div>`;return sourceEvents(a).map(e=>`<div class="evidence-item"><div class="evidence-top"><button class="evidence-title" data-evidence="${e.id}">${e.title}</button><span class="evidence-ref">${e.id}</span></div><div class="evidence-meta">${e.date} · ${e.source}</div><div class="evidence-meta"><span class="status ${e.excluded?'':e.superseded?'green':!e.verified?'amber':e.adverse?'red':'green'}">${e.excluded?'Excluded, Not used in scenarios':e.superseded?'Corrected by a subsequent disclosure':!e.association?'Entity association requires review':!e.verified?'Associated, Facts Awaiting Verification':e.adverse?'Verified · Adverse Signal':'Verified · Stable / Positive'}</span></div>${!e.association&&!e.excluded?'<p class="evidence-body">The similarly named entity is excluded from scenarios; Verify the entity and facts first. </p>':''}<div class="evidence-actions"><button class="text-button" data-evidence="${e.id}">View Evidence</button>${!e.excluded?`<button class="text-button" data-feedback="exclude" data-event="${e.id}">Not Relevant to This Account</button>`:`<button class="text-button" data-feedback="restore" data-event="${e.id}">Restore Association</button>`}${!e.association&&!e.excluded?`<button class="text-button" data-feedback="link" data-event="${e.id}">Confirm Entity Association</button>`:''}</div></div>`).join('')}
function monitorPanel(){const a=c(),o=outlook(a),m=metrics(a),ar=arMetrics(a),d=activeDecision(),pending=pendingReviews();return `<div class="ai-eyebrow">Follow the account, beyond an individual news item</div>${pending.length?`<div class="alert-note"><strong>A new change requires review of the prior decision</strong>${pending.map(u=>esc(u.title)).join('; ')}<br>Prior Decision“${esc(d.selection)}”is retained, Check whether it remains appropriate. <br><button class="text-button" data-ai-tab="decision">View Decision & Trigger →</button></div>`:''}<div class="lead-insight">${o.n>=2?'Revenue has not changed materially, but the customer’s operating environment is changing. ':o.n===1?'A new signal needs validation, before changing the overall approach. ':'Use a stable business baseline, to identify the next opportunity early. '}</div><p class="lead-copy">${o.n>=2?'Historical revenue alone does not explain future risk. Connect operating and credit signals to the customer’s contracts, revenue and receivables exposure, to decide what to do now. ':'Validate implications against customer history and disclosures, Do not treat unconfirmed signals as financial results. '}</p><div class="decision-box"><h3>${o.n?'Future Revenue Pressure Scenario':'Current Revenue Baseline'}</h3><p>${o.n?`Q4 Baseline ${million(o.baseline)} → ${million(o.lower)}–${million(o.upper)} (Illustrative). `:`Q4 ${million(o.baseline)}, Validate opportunity revenue first. `}<br>Recommendation: ${recommendation(a)}. </p><button class="text-button" data-ai-tab="decision">${d?'Review Recorded Decision':'Choose Next Action'} →</button></div>${d?`<div class="memory-note"><b>Account Context Saved</b><br>${esc(d.selection)} · ${esc(d.owner)}<br>${pending.length?'Review the existing approach, without overwriting the prior decision. ':'Check whether its assumptions still hold, Avoid duplicate tasks. '}</div>`:''}<div class="signal-summary-line"><span class="status purple">${o.n}  active adverse signals</span><span class="status">Revenue / AR / cross-check margin information</span></div><div class="source-tabs" role="tablist" aria-label="Supporting Evidence">${[['history','Historical Data'],['latest','Latest Business Data'],['external','External Signals']].map(([v,t])=>`<button role="tab" aria-selected="${ui.evidence===v}" data-evidence-tab="${v}" class="${ui.evidence===v?'active':''}">${t}</button>`).join('')}</div><div id="evidence-panel">${evidencePanel()}</div><section class="analysis-section"><div class="analysis-title"><h3>What does this mean for the account?？</h3><span>Scenario Interpretation · Not a Certain Outcome</span></div><div class="impact-row"><span class="impact-icon">↗</span><div><h4>Future Revenue</h4><p>${o.n?`Current Q4 Baseline <strong>${million(o.baseline)}</strong>. If operating pressure affects usage or renewals, the illustrative revenue range is <strong>${million(o.lower)}–${million(o.upper)}</strong>. `:`Q4 baseline is <strong>${million(o.baseline)}</strong>; Verified signals do not currently require a downside scenario. Validate expansion opportunities first, Do not immediately add revenue. `}</p><button class="text-button" data-evidence="scenario">View Scenario Basis H1 + N2 + E →</button></div></div><div class="impact-row"><span class="impact-icon">◷</span><div><h4>Collection & Liquidity</h4><p>Current Open AR <strong>${million(ar.open)}</strong>, Overdue <strong>${million(ar.overdue)}</strong>. ${acceptedSignals(a).some(e=>e.type==='credit')?'Credit changes warrant closer follow-up on balances not yet due, Exposure is not an incurred loss. ':'Schedule routine follow-up on due balances, and watch for credit changes. '}</p></div></div><div class="impact-row"><span class="impact-icon">◫</span><div><h4>Leasing Profitability</h4><p>Monthly Gross Margin <strong>${pct(m.margin)}</strong>, compared with the prior period ${m.margin<m.priorMargin?'Decline':'Improvement'} ${Math.abs((m.margin-m.priorMargin)*100).toFixed(1)}  percentage points. Review hardware and service cost drivers separately. </p><button class="text-button" data-ai-tab="profit">Review Profitability Drivers →</button></div></div><p class="assumption">${o.n?'Scenario Assumptions: Use verified adverse signals to define '+pct(o.low)+'–'+pct(o.high)+' pressure range, Not a calibrated forecast. ':'Continue reviewing future developments. '} Unverified, excluded and corrected signals are not used in this scenario. </p></section><button class="primary full-width" data-ai-tab="decision">${d?'View Review Status':'Choose Next Action'} →</button>`}
function profitPanel(){const a=c(),m=metrics(a),r=ui.profitSlice,rev=r?r.revenue:m.revenue,hwRev=r?r.hwRev:m.hwRev,svRev=r?r.svRev:m.svRev,hwCost=r?r.hwCost:m.hwCost,svCost=r?r.svCost:m.svCost,cost=hwCost+svCost,gp=rev-cost,oldCost=r?r.priorCost:m.priorCost,margin=gp/rev,oldMargin=(rev-oldCost)/rev,delta=cost-oldCost;return `<div class="ai-eyebrow">AI Priority / Profitability Interpretation</div><div class="lead-insight">${delta>0?'Revenue looks stable, but margin changes can emerge in the cost structure. ':'Profitability Improvement, Separate durable improvements from temporary effects. '}</div><p class="lead-copy">Analysis Scope: ${r?esc(r.key)+' · '+r.count+' items Tranche':esc(a.name)}. ${r?'Aggregated from the selected row, Explain revenue and costs for this dimension. ':'Use consistent hardware and service revenue and costs, to explain this account’s profitability changes. '}</p><div class="profit-value">${pct(margin)}<small>Current Gross Margin · Prior ${pct(oldMargin)} · ${delta>0?'Decline':'Improvement'} ${Math.abs((margin-oldMargin)*100).toFixed(1)} pp</small></div><div class="breakdown-grid"><div>Hardware Gross Margin<strong>${pct((hwRev-hwCost)/hwRev)}</strong></div><div>Service Gross Margin<strong>${pct((svRev-svCost)/svRev)}</strong></div></div><div class="profit-bridge"><div class="bridge-row"><span>Historical gross profit on the same revenue basis</span><b>${usd(rev-oldCost)}</b></div><div class="bridge-row"><span>${delta>0?'Reduction from higher costs':'Increase from lower costs'}</span><b>${delta>0?'−':'+'}${usd(Math.abs(delta))}</b></div><div class="bridge-row"><span>Current Gross Profit</span><b>${usd(gp)}</b></div></div><div class="analysis-section"><h3>What should Finance investigate?？</h3><div class="impact-row"><span class="impact-icon">01</span><div><h4>Why did costs change?</h4><p>${r?'Validate allocation and service scope first, Do not confuse allocation changes with operating deterioration. ':`Hardware Cost Change ${usd(m.hwIncrease)}, Service Cost Change ${usd(m.svIncrease)}. Illustrative drivers include expanded maintenance scope and service delivery costs; The business owner must verify these drivers. `}</p></div></div><div class="impact-row"><span class="impact-icon">02</span><div><h4>Which contract terms could improve performance?</h4><p>Review equipment maintenance responsibilities, included services and additional-service charging boundaries. Address cost drivers first, then consider whether a general price increase is warranted. </p></div></div><div class="impact-row"><span class="impact-icon">03</span><div><h4>Cross-check external operating signals</h4><p>${r?'This is an aggregated view, Do not apply one customer’s news to all customers. Select a specific customer for further review. ':outlook(a).n?'The customer may be reducing budgets. Consider renewal and payment capacity when improving margins. ':'Demand growth may support broader service coverage, Confirm budget and cost capacity before committing terms. '}</p></div></div></div>${r?'<button class="secondary full-width" data-command="clear-profit-slice">Return to Current Account Insights</button>':`<button class="secondary full-width" data-ai-tab="decision">Use Profitability Insights in the Decision →</button><details id="repricing"><summary>Supporting Capability: Repricing and Contract Recommendations</summary><p>Illustrative calculation using this account’s monthly revenue and costs, Unverified competitor pricing is excluded, Contracts are not changed automatically. </p><label class="form-field"><span>Price Adjustment: <b id="price-label">${ui.repricing}%</b></span><input id="repricing-input" type="range" min="-5" max="8" step="1" value="${ui.repricing}"></label><label class="form-field"><span>Additional Monthly Service Package Cost (USD)</span><input id="service-cost" type="number" min="0" max="1000000" step="1000" value="${ui.servicePackage}"></label><div class="repricing-result" id="repricing-result">${repricingResult()}</div><p>Contract Recommendation: Define service scope, set additional-service pricing, and phase commitments. When operating pressure exists, also assess customer acceptance. </p></details>`}<p class="assumption">Gross margin uses illustrative cost allocations, Excludes unavailable financing, tax and shared costs; This is not a complete net profit calculation. </p>`}
function repricingResult(){const m=metrics(c()),rev=m.revenue*(1+ui.repricing/100),gp=rev-m.cost-ui.servicePackage;return `Scenario Margin at Current Volume<b>${pct(gp/rev)}</b>Monthly Gross Profit ${usd(gp)} · Assumes costs other than the service package remain unchanged, Customer acceptance is not guaranteed. `}
function formDraft(){const a=c(),d=activeDecision();if(!edits[a.id])edits[a.id]={selection:d?.selection||'',comments:'',owner:d?.owner||a.owner,nextReview:nextDate(dataDate(),7),frequency:d?.frequency||'daily',rules:d?[...d.rules]:['credit','business','ar','margin'],threshold:String(d?.threshold??2),outcome:'Not Yet Validated'};return edits[a.id]}
function nextDate(date,days){return new Date(Date.parse(date+'T00:00:00Z')+days*86400000).toISOString().slice(0,10)}
function decisionChoices(a){return [recommendation(a),'Maintain the current approach, Continue Observing','Verify costs and service scope first, then discuss pricing','Defer Commercial Proposal, Escalate Finance Review']}
function legacyDecisionPanel(){const a=c(),s=state(),d=activeDecision(),draft=formDraft(),pending=pendingReviews(),choices=[...new Set([...decisionChoices(a),...(draft.selection?[draft.selection]:[])])];return `<div class="ai-eyebrow">Save the decision to account context, Continue monitoring</div><div class="lead-insight">${pending.length?'When new evidence appears, review the original decision. ':d?'Existing Decision, Review whether it remains valid. ':'Decide how to respond, then schedule a review. '}</div><p class="lead-copy">Retain evidence, the selected action and review conditions. When a new event occurs, AI it is linked to the existing decision, rather than generating an isolated recommendation. </p>${d?`<div class="memory-note"><b>Current Decision · V${s.decisions.length}</b><br>${esc(d.selection)}<br>${esc(d.owner)} · Next Review ${esc(d.nextReview)}<br>AI Recommendation: ${esc(d.recommendation)}</div><div class="monitor-status"><strong>${s.paused?'Ⅱ Monitoring Paused (Local Demonstration)':pending.length?'● Review Existing Decision':'● Added to Watchlist (Local Demonstration)'}</strong><button data-command="pause">${s.paused?'Resume Monitoring':'Pause Monitoring'}</button></div>${pending.length?`<div class="alert-note"><strong>${pending.length}  updates matched review conditions</strong>${pending.map(u=>`${esc(u.title)}<br>Trigger: ${u.triggered.map(x=>ruleNames[x]).join(', ')}`).join('<br>')}<br>The original decision has not been replaced. </div>`:''}<div class="next-update"><p>Demonstration: Load the next illustrative update, and check its relevance to the recorded decision. </p><button data-command="simulate" ${s.step>=4?'disabled':''}>${s.step>=4?'For this account 4  demonstration updates have all been loaded':'▷ Simulate Next Update'}</button></div>`:''}<div class="decision-box"><h3>Current AI Recommendation</h3><p>${recommendation(a)}. </p></div><form id="decision-form"><label class="form-field"><span>Finance Selection *</span><select name="selection" required><option value="">Select an Action</option>${choices.map(t=>`<option value="${esc(t)}" ${draft.selection===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="form-field"><span>Decision Rationale / Questions to Validate</span><textarea name="comments" maxlength="1500" placeholder="Record the supporting rationale, for the next review. ">${esc(draft.comments)}</textarea></label><div class="form-two"><label class="form-field"><span>Follow-up Owner *</span><select name="owner">${['Finance BP · Alex','AR Owner · Jamie','Account Owner · Sam'].map(o=>`<option ${draft.owner===o?'selected':''}>${o}</option>`).join('')}</select></label><label class="form-field"><span>Next Review Date *</span><input name="nextReview" type="date" min="${dataDate()}" value="${esc(draft.nextReview)}" required></label></div><label class="form-field"><span>Monitoring Frequency</span><select name="frequency"><option value="daily" ${draft.frequency==='daily'?'selected':''}>Daily Summary (Plan)</option><option value="weekly" ${draft.frequency==='weekly'?'selected':''}>Weekly Summary (Plan)</option></select></label><h3 style="margin-top:20px">Which changes should prompt a review?？</h3><div class="rule-list">${Object.entries(ruleNames).map(([key,name])=>`<label><input type="checkbox" name="rules" value="${key}" ${draft.rules.includes(key)?'checked':''}><span>${name}</span></label>`).join('')}</div><label class="form-field"><span>Further Gross Margin Decline Threshold (Percentage Points)</span><input name="threshold" type="number" min="0.5" max="10" step="0.5" value="${esc(draft.threshold)}" required></label>${d?`<label class="form-field"><span>Feedback on the Prior Decision</span><select name="outcome">${['Not Yet Validated','Prior Decision Remains Valid','Prior Decision Needs Adjustment','Results Improved, Continue Observing'].map(t=>`<option ${draft.outcome===t?'selected':''}>${t}</option>`).join('')}</select></label>`:''}<button class="primary full-width" type="submit">${d?'Record Review and Continue Monitoring':'Save Decision and Monitor'} →</button><p class="commit-boundary">The saved record contains AI account context and a review plan; No contract changes, No invoices created, No notifications sent. The local prototype does not run scheduled data collection. </p></form>${s.decisions.length?`<hr class="assistant-divider"><h3>Account Decision & Review History</h3><div class="monitor-trail">${timeline(a)}</div>`:''}`}
function legacyTimeline(a){const s=state(a.id),entries=[...s.decisions.map((d,i)=>({time:d.savedAt,html:`<time>${esc(d.snapshotDate)} · Decision V${i+1}</time><strong>${esc(d.selection)}</strong><p>${esc(d.comments||'No comments provided')}</p><p>Prior Decision Feedback: ${esc(d.outcome)}<br>Basis ${d.evidenceIds.join(', ')||'Current Business Data'} · ${esc(d.owner)}</p><button class="text-button" data-decision-id="${d.id}">View Original Evidence & Conditions →</button>`})),...s.updates.map(u=>({time:u.savedAt,html:`<time>${u.date} · Simulation Update</time><strong>${esc(u.title)}</strong><p>${esc(u.note)}</p><p>${u.triggered.length?'Matched: '+u.triggered.map(k=>ruleNames[k]).join(', '):'No current review condition matched'}${u.paused?' · Monitoring was paused at the time':''}</p>`}))].sort((a,b)=>b.time.localeCompare(a.time));return entries.map(e=>`<div class="trail-item">${e.html}</div>`).join('')}
function watchPanel(){const rows=accounts.filter(a=>activeDecision(a.id)).filter(a=>ui.watchFilter==='all'||pendingReviews(a.id).length);return `<div class="ai-eyebrow">My Account Watchlist</div><div class="lead-insight">Follow changes after a decision. </div><p class="lead-copy">Each watchlist entry links to an account decision, owner and trigger conditions. These are local demonstration plans, not live news subscriptions. </p><div class="watch-toolbar"><button data-watch-filter="all" class="${ui.watchFilter==='all'?'active':''}">All Plans</button><button data-watch-filter="review" class="${ui.watchFilter==='review'?'active':''}">Needs Review</button></div>${rows.map(a=>{const d=activeDecision(a.id),s=state(a.id),p=pendingReviews(a.id);return `<button class="watch-row" data-watch-account="${a.id}"><b>${esc(a.name)}</b><small>${esc(d.selection)}<br>${esc(d.owner)} · Review ${d.nextReview}</small><span class="status ${p.length?'amber':s.paused?'':'green'}">${p.length?'New Changes, Needs Review':s.paused?'Monitoring Paused':'Monitoring Planned'}</span></button>`}).join('')||'<div class="no-results">No watchlist entries match this filter. <br>Save a decision and review conditions for an account first. </div>'}<button class="text-button" data-ai-tab="decision">Return to Current Account Decision →</button>`}
function showEvidence(id){const a=c(),m=metrics(a),ar=arMetrics(a),f=forecast(a),o=outlook(a);if(id==='scenario'){dialog('Account Scenario Basis',`<p>This range illustrates a financial decision scenario, not an incurred loss or a certain forecast. </p><dl><dt>Baseline N2</dt><dd>${usd(f.standard)} Standard Transactions + ${usd(f.change)} Confirmed Changes = ${usd(f.baseline)}</dd><dt>History H1</dt><dd>Historical revenue is near current levels, but does not independently reveal external pressure. </dd><dt>Valid External Evidence</dt><dd>${acceptedSignals(a).map(e=>e.id+' '+esc(e.title)).join('<br>')||'No valid adverse signals'}</dd><dt>Pressure Assumptions</dt><dd>${pct(o.low)}–${pct(o.high)}, The illustrative range varies with the number of adverse signals; Unverified leads are excluded. </dd><dt>Revenue Scenario</dt><dd>${million(o.lower)}–${million(o.upper)}</dd><dt>Exposure</dt><dd>${million(o.exposureLow)}–${million(o.exposureHigh)}, Not an impairment or revenue adjustment. </dd></dl><p>Existing Decision: ${esc(activeDecision()?.selection||'Not Yet Recorded')}. The decision changes the response, It does not automatically remove risk assumptions. </p>`);return}if(id.startsWith('E')){const e=sourceEvents(a).find(e=>e.id===id);dialog(e.title,`<div class="dialog-alert">Illustrative Evidence, Not Actual News. No external news source is connected. </div><dl><dt>Associated Account</dt><dd>${esc(a.name)} / ${a.code}</dd><dt>Source</dt><dd>${e.source}</dd><dt>Publication Date</dt><dd>${e.date}</dd><dt>Business Summary</dt><dd>${e.body}</dd><dt>Association Status</dt><dd>${e.excluded?'Excluded':e.association?'Entity Associated':'Similarly Named Entity Requires Review'}; ${e.verified?'Illustrative original disclosure checked':'Facts Awaiting Verification'}</dd><dt>Used in Scenario?</dt><dd>${acceptedSignals(a).some(x=>x.id===id)?'Included in Downside Scenario':e.superseded?'Corrected by Subsequent Disclosure':'Excluded from Downside Scenario'}</dd></dl>`);return}const descriptions={H1:['Historical Revenue Record',`Illustrative six-month revenue near ${million(a.revenue)} /  Month. This record supports internal trend review, not a new external event. `],H2:['Revenue & Cost Comparison',`Revenue ${usd(m.revenue)}; Historical Cost ${usd(m.priorCost)}; Current Cost ${usd(m.cost)}. Gross margin changes from ${pct(m.priorMargin)} to ${pct(m.margin)}. `],N1:['Invoice Payment Status',`Current Open ${usd(ar.open)}; Overdue ${usd(ar.overdue)}. Matches the selected account’s invoice records; A different basis from contract revenue recognition. `],N2:['Standard Transactions & Changes Baseline',`Q4 Standard Transactions ${usd(f.standard)}, Confirmed Changes ${usd(f.change)}. Pending Changes ${usd(f.pending)} Excluded from Baseline. `]};dialog(descriptions[id][0],`<p>${descriptions[id][1]}</p><p>Source: Nexbill ${id==='N1'?'Invoice Payment Status Tracking':'Finance / Revenue Reporting'} Business Workspace Mockup, All amounts are illustrative. </p>`)}
function recordDecision(form){const a=c(),s=state(),data=new FormData(form),rules=data.getAll('rules');if(!form.reportValidity())return;if(!rules.length){toast('Select at least one review condition. ');return}const threshold=Number(data.get('threshold'));const record={id:'D-'+a.code+'-'+(s.decisions.length+1),selection:String(data.get('selection')),comments:String(data.get('comments')).trim(),owner:String(data.get('owner')),nextReview:String(data.get('nextReview')),frequency:String(data.get('frequency')),rules,threshold,outcome:String(data.get('outcome')||'Not Yet Validated'),recommendation:recommendation(a),evidenceIds:acceptedSignals(a).map(e=>e.id),evidenceSnapshot:acceptedSignals(a).map(e=>({id:e.id,title:e.title,date:e.date,source:e.source})),financialSnapshot:{metrics:metrics(a),forecast:forecast(a),ar:arMetrics(a)},snapshotDate:dataDate(),baselineStep:s.step,baselineMargin:metrics(a).margin,baselineAR:arMetrics(a),outlook:outlook(a),savedAt:new Date().toISOString(),execution:'No Transactions Executed'};if(saveState(a.id,{...s,paused:false,decisions:[...s.decisions,record]},'Decision and review conditions saved locally. ')){delete edits[a.id];render()}}
function simulate(){const a=c(),s=state(),d=activeDecision();if(!d){toast('Select Continue Monitoring first, or use Nexbill to submit a business request. ');return}if(s.step>=4)return;const step=s.step+1,definitions=[null,{date:'2026-09-30',title:'New credit downgrade disclosed',type:'credit',note:'The external credit change followed the decision. Link new evidence E5 to the prior decision, Review collection and commercial terms. '}, {date:'2026-10-02',title:a.kind<3?'Company clarifies the impact of industry investment changes':'Company clarifies expansion scope',type:'business',note:'E6 corrected E3 the impact scope for this account; Remove outdated adverse evidence, and ask Finance to review the prior assessment. '}, {date:'2026-10-07',title:'New Payment Received, Overdue Receivables Declined',type:'ar',note:'Load an illustrative payment record; A decline in overdue balances is not an“Increase in Overdue Balances”Trigger Condition. Earlier unreviewed items remain open. '}, {date:'2026-10-09',title:'Service Delivery Cost Increased, Further Margin Pressure',type:'margin',note:'Illustrative service costs increased, Gross margin declined from the original snapshot by 3  percentage points. Assess against the current decision threshold. '}];const update={...definitions[step],step,triggered:[],paused:s.paused,savedAt:new Date().toISOString()};if(!s.paused&&d.rules.includes(update.type)){if(update.type==='credit'||update.type==='business')update.triggered=[update.type];if(update.type==='margin'){const future=metrics(a).margin-.03;if((d.baselineMargin-future)*100+1e-8>=d.threshold)update.triggered=['margin']}}if(saveState(a.id,{...s,step,updates:[...s.updates,update]},update.triggered.length?'A new change matched review conditions: Review the prior decision. ':'Simulation update archived, No current review condition matched. '))render()}
function togglePause(){const s=state(),d=activeDecision();if(!d)return;const paused=!s.paused;let updates=s.updates;if(!paused)updates=updates.map(u=>{if(u.step<=d.baselineStep||!u.paused)return u;const trigger=d.rules.includes(u.type)&&(u.type==='credit'||u.type==='business'||u.type==='margin'&&(d.baselineMargin-metrics(c()).margin)*100+1e-8>=d.threshold);return {...u,paused:false,triggered:trigger?[u.type]:[],note:u.note+' This update was reviewed when monitoring resumed. '}});if(saveState(c().id,{...s,paused,updates},paused?'Local Monitoring Paused, Existing decision retained. ':'Monitoring Resumed, Changes during the pause have been reviewed. '))render()}
function chooseAccount(id){ui.account=Number(id);ui.search='';ui.watch=false;ui.profitSlice=null;ui.servicePackage=0;ui.repricing=0;render()}
function exportReport(){const a=c();let rows,name;if(page()==='billing'){rows=[['Invoice','Due','Amount_USD','Paid_USD','Open_USD','Status'],...invoices(a).filter(x=>ui.billingStatus==='all'||x.status===ui.billingStatus).map(x=>[x.id,x.due,x.amount,x.paid,x.open,x.status])];name='invoice-payment'}else if(page()==='profit'){rows=[['Dimension','Hardware_revenue','Hardware_cost','Service_revenue','Service_cost','Gross_margin'],...profitRows().map(r=>[r.key,r.hwRev,r.hwCost,r.svRev,r.svCost,pct(r.margin)])];name='profitability'}else{const f=forecast(a);rows=[['Component','Q4_USD'],['Standard transactions',f.standard],['Effective change events',f.change],['Baseline',f.baseline],['Pending event excluded',f.pending]];name='revenue-baseline'}const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=name+'-'+a.code+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Illustrative data exported for the selected report scope. ')}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.aiTab){ui.aiTab=el.dataset.aiTab;ui.watch=false;ui.open=true;if(ui.aiTab==='profit')ui.profitSlice=null;hostRender();assistantRender();return}if(el.dataset.decisionId){showDecision(el.dataset.decisionId);return}if(el.dataset.evidenceTab){ui.evidence=el.dataset.evidenceTab;assistantRender();return}if(el.dataset.evidence){showEvidence(el.dataset.evidence);return}if(el.dataset.feedback){const s=state(),feedback={...s.feedback};if(el.dataset.feedback==='restore')delete feedback[el.dataset.event];else feedback[el.dataset.event]=el.dataset.feedback;if(saveState(c().id,{...s,feedback},'Evidence association feedback saved, Account interpretation updated. '))assistantRender();return}if(el.dataset.explainProfit!==undefined){ui.profitSlice=profitRows()[Number(el.dataset.explainProfit)];ui.aiTab='profit';ui.open=true;ui.watch=false;render();return}if(el.dataset.reportTab){ui.reportTab=el.dataset.reportTab;hostRender();return}if(el.dataset.watchFilter){ui.watchFilter=el.dataset.watchFilter;assistantRender();return}if(el.dataset.watchAccount!==undefined){chooseAccount(el.dataset.watchAccount);ui.aiTab='decision';assistantRender();return}if(el.dataset.invoice){const inv=invoices(c()).find(x=>x.id===el.dataset.invoice);dialog('Invoice '+inv.id,`<dl><dt>Customer</dt><dd>${esc(c().name)}</dd><dt>Tranche</dt><dd>${inv.tranche}</dd><dt>Invoice Date</dt><dd>${inv.issued}</dd><dt>Due Date</dt><dd>${inv.due}</dd><dt>Billing / Collection</dt><dd>${usd(inv.amount)} / ${usd(inv.paid)}</dd><dt>Open / Status</dt><dd>${usd(inv.open)} / ${inv.status}</dd></dl><p>Illustrative Business Records, Read-only View. </p>`);return}const cmd=el.dataset.command;if(cmd==='toggle-ai'){ui.open=!ui.open;render()}if(cmd==='close-ai'){ui.open=false;render();$('.ai-launch').focus()}if(cmd==='watchlist'){ui.watch=true;ui.open=true;render()}if(cmd==='close-dialog')$('#detail-dialog').close();if(cmd==='clear-profit-slice'){ui.profitSlice=null;assistantRender()}if(cmd==='simulate')simulate();if(cmd==='pause')togglePause();if(cmd==='export')exportReport();if(cmd==='sources')dialog('Design References & Scope',`<p><b>Intelligence Platform deck: </b>Internal activity and external operating, credit, and industry signals are combined, to explain future revenue, collection and renewal pressure; Customer/Country/Tranche Profitability interpretation is another focus. </p><p><b>KUT: </b>Invoice Payment Status Tracking (169 Page), Change Event Report (167 Page), ARS Revenue (173 Page)and subscription workflows provide business context. </p><p><b>Finance & Accounting BSR: </b>Hardware/Service Details, Revenue & Cost Definitions, Change Recalculation, Reconciliation & Original Invoice Links. Do not treat BSR as an external news source. </p><p>For this design, account signals and decision review are priorities; Base reports provide facts, Repricing is a supporting capability. Actual cost allocation and PN report definitions require business confirmation. </p>`)});
document.addEventListener('input',e=>{if(e.target.id==='account-search'){ui.search=e.target.value;const matches=accountOptions();$('#account-select').innerHTML='<option value="" disabled selected>Select a matching account</option>'+matches.map(a=>`<option value="${a.id}">${esc(a.name)} · ${a.code}</option>`).join('');if(!matches.length)$('#account-select').innerHTML='<option value="" disabled selected>No matching accounts</option>';return}if(e.target.closest('#decision-form')){const data=new FormData(e.target.closest('form')),d=formDraft();for(const key of ['selection','comments','owner','nextReview','frequency','threshold','outcome'])if(data.has(key))d[key]=String(data.get(key));d.rules=data.getAll('rules');return}if(e.target.id==='repricing-input'||e.target.id==='service-cost'){if(e.target.id==='repricing-input')ui.repricing=Number(e.target.value);else ui.servicePackage=Math.max(0,Math.min(1000000,Number(e.target.value)||0));$('#price-label').textContent=ui.repricing+'%';$('#repricing-result').innerHTML=repricingResult()}});
document.addEventListener('change',e=>{if(e.target.id==='account-select'&&e.target.value!=='')chooseAccount(e.target.value);if(e.target.id==='invoice-status'){ui.billingStatus=e.target.value;hostRender()}if(e.target.id==='profit-scope'||e.target.id==='profit-dimension'){ui[e.target.id==='profit-scope'?'profitScope':'profitDimension']=e.target.value;ui.profitSlice=null;render()}if(e.target.closest('#decision-form'))e.target.dispatchEvent(new Event('input',{bubbles:true}))});
document.addEventListener('submit',e=>{if(e.target.id==='decision-form'){e.preventDefault();recordDecision(e.target)}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('hashchange',()=>{ui.profitSlice=null;if(page()==='profit')ui.aiTab='profit';render()});

function showDecision(id){const d=state().decisions.find(x=>x.id===id);if(!d)return;dialog('Historical Decision · '+d.id,'<dl><dt>Finance Decision</dt><dd>'+esc(d.selection)+'</dd><dt>At the Time AI Recommendation</dt><dd>'+esc(d.recommendation)+'</dd><dt>Reason</dt><dd>'+esc(d.comments||'Not Provided')+'</dd><dt>Owner</dt><dd>'+esc(d.owner)+'</dd><dt>Review Plan</dt><dd>'+esc(d.nextReview)+' / '+(d.frequency==='daily'?'Daily Summary':'Weekly Summary')+'</dd><dt>Review Conditions</dt><dd>'+d.rules.map(k=>ruleNames[k]).join(', ')+'; Margin Threshold '+d.threshold+' pp</dd><dt>Evidence at the Time</dt><dd>'+(d.evidenceSnapshot||[]).map(e=>esc(e.id+' · '+e.date+' · '+e.title+' / '+e.source)).join('<br>')+'</dd><dt>Revenue Baseline</dt><dd>'+million(d.outlook.baseline)+'</dd><dt>Scenario at the Time</dt><dd>'+million(d.outlook.lower)+'–'+million(d.outlook.upper)+'</dd><dt>Subsequent Feedback</dt><dd>'+esc(d.outcome)+'</dd></dl><p>This is a snapshot from the time of recording, Later corrections do not overwrite it. All Data Is Illustrative; No Transactions Executed. </p>')}
